public static function convertToExcelAddressValue(string $openOfficeAddress): string
{
    $quotedSheetName = "'(?:[^']|'')*'";
    $sheetName = "(?:$quotedSheetName|[^.:']+)";
    $cellAddress = "[^.:']+";

    // Cell range 3-d reference
    // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
    //  and assume that the second worksheet reference is the same as the first
    $addressPattern = '/(?:'
        . '\$?(?<sheet1>' . $sheetName . ')\.(?<cell1>' . $cellAddress . ')'
        . '(?::(?:\$?(?<sheet2>' . $sheetName . ')\.)?(?<cell2>' . $cellAddress . '))?'
        . '|'
        . '\.(?<cell3>' . $cellAddress . ')'
        . '(?::\.(?<cell4>' . $cellAddress . '))?'
        . '|'
        . '(?<quoted>' . $quotedSheetName . ')'
        . ')/miu';

    return (string) preg_replace_callback(
        $addressPattern,
        static function (array $matches): string {
            if (($matches['quoted'] ?? '') !== '') {
                return $matches['quoted'];
            }

            if (($matches['cell3'] ?? '') !== '') {
                return $matches['cell3'] . (($matches['cell4'] ?? '') === '' ? '' : ':' . $matches['cell4']);
            }

            $excelAddress = $matches['sheet1'] . '!' . $matches['cell1'];

            return $excelAddress . (($matches['cell2'] ?? '') === '' ? '' : ':' . $matches['cell2']);
        },
        $openOfficeAddress
    );
}

